using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace MonitorSlice {
static class MirrorTests {
 [System.Runtime.InteropServices.DllImport("MonitorSlice.Capture.dll",CallingConvention=System.Runtime.InteropServices.CallingConvention.Cdecl)]static extern int SampleCapturePixel(IntPtr handle,int x,int y,out uint color);
 static void Wait(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
 public static void Run(){var screen=Screen.AllScreens.First(s=>!Displays.Virtual().Any(d=>d.Name==s.DeviceName));var r=screen.Bounds;var dest=new Rectangle(r.X,r.Y,r.Width/2,r.Height/2);var v=new Viewport{Source=r,Destination=dest};bool passed=false;var colors=new List<object>();using(var f=new Form{Text="Mirror test source",TopMost=true,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,AutoScaleMode=AutoScaleMode.None,Bounds=new Rectangle(r.X+200,r.Y+200,400,300),BackColor=Color.Red}){DesktopSurface surface=null;VirtualSession session=null;try{f.Show();Native.ShowWindowAsync(f.Handle,5);Native.SetWindowPos(f.Handle,IntPtr.Zero,r.X+200,r.Y+200,400,300,0x214);Wait(300);if(Environment.CommandLine.Contains("--session")){session=new VirtualSession();session.Recover();session.Start(r,Layouts.Create("grid"),false);v=session.Views[0];}else{surface=new DesktopSurface(r,new List<Viewport>{v});surface.Open();}foreach(var c in new[]{Color.Red,Color.Lime,Color.Blue}){f.BackColor=c;f.Refresh();Wait(900);uint sampled;System.Runtime.InteropServices.Marshal.ThrowExceptionForHR(SampleCapturePixel(v.Capture,400,350,out sampled));var actual=Color.FromArgb(unchecked((int)sampled));bool ok=Math.Abs(actual.R-c.R)<20&&Math.Abs(actual.G-c.G)<20&&Math.Abs(actual.B-c.B)<20;colors.Add(new{Expected=c.ToArgb(),Actual=actual.ToArgb(),Passed=ok});if(!ok)throw new Exception("GPU 원본 복제 갱신 실패");}passed=true;}finally{if(session!=null)session.Stop();if(surface!=null)surface.Dispose();string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","mirror-test.json");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,new JavaScriptSerializer().Serialize(new{Passed=passed,Colors=colors,TopologyChanged=Environment.CommandLine.Contains("--session"),SessionTest=Environment.CommandLine.Contains("--session"),InputTested=false}));}}}
}
}
